corrected_code:
package metrics

import (
	"net/http"

	"github.com/gin-gonic/gin"
	"myapp/auth"
	"myapp/telemetry"
)

func SetupTelemetryRoutes(r *gin.Engine, collector telemetry.Collector) {
	metricsGroup := r.Group("/metrics")
	metricsGroup.Use(auth.TenantTokenGuard())

	metricsGroup.GET("/tenants/:tenantID/uptime", func(c *gin.Context) {
		tenantID := c.Param("tenantID")
		authTenant := c.GetString("auth_tenant_id")

		if authTenant != tenantID {
			c.JSON(http.StatusForbidden, gin.H{"error": "Unauthorized tenant telemetry query"})
			return
		}
		uptime := collector.GetTenantUptime(c.Request.Context(), tenantID)
		c.JSON(http.StatusOK, gin.H{"tenant": tenantID, "uptime_pct": uptime})
	})
}
